#!/usr/bin/env python3
"""Unified severity standard (Praise 2026-10-26): merger P0 alert reads severity == "P0" and p0_candidate: true;
coverage-only P2 never becomes a ticket / ledger row. Local only. Run: python3 test/test_severity_unify.py"""
import os, sys, json, unittest
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(os.path.dirname(HERE), "bin"))
import merger, finding_policy as P

def fixture_pr():
    # generated by argus/tests/fixtures-p0-candidate.mjs from nightly.mjs's real p0Candidate (kept in sync by argus test)
    return json.load(open(os.path.join(HERE, "p0-candidate-report.json")))["prs"][0]

class MergerP0Alert(unittest.TestCase):
    def test_generated_p0_candidate_alerts(self):
        pr = fixture_pr()
        self.assertEqual(pr["severity"], "P1", "p0_candidate keeps level P1")
        self.assertTrue(pr["failed_checks"][0]["p0_candidate"])
        self.assertTrue(merger.is_p0_alert(pr), "old check (severity == P0 only) missed this: always silent")
    def test_severity_p0_and_negatives(self):
        self.assertTrue(merger.is_p0_alert({"severity": "P0"}))
        self.assertTrue(merger.is_p0_alert({"severity": "P1", "findings": [{"severity": "P0"}]}))
        self.assertTrue(merger.is_p0_alert({"severity": "P1", "p0_candidate": True}))
        for pr in ({"severity": "P1"}, {"severity": "P1", "findings": [{"severity": "P1", "p0_candidate": False}]},
                   {"severity": "P2", "failed_checks": None}, None, {"severity": "P1", "findings": ["x"]}):
            self.assertFalse(merger.is_p0_alert(pr), pr)

class CoverageNotInLedger(unittest.TestCase):
    def test_coverage_p2_never_ticket_even_if_ruled_fix(self):
        for src in ("coverage-gate", "own-tests"):
            self.assertIsNone(P.own_pr_ticket({"severity": "P2", "source": src}, 1000, {1000}), src)
    def test_stated_acceptance_still_ticket(self):
        self.assertEqual(P.own_pr_ticket({"severity": "P2", "source": "stated-acceptance"}, 1000, set()), "P2")

if __name__ == "__main__": unittest.main()
